"Kelimeleri boşlukla ayırarak yazın; hepsi geçen maddeler kalır. Tırnak içindeki ifade tek parça aranır. Büyük/küçük harf ve şapka farkı gözetilmez.":["শব্দগুলো ফাঁক দিয়ে লিখুন; সব শব্দ থাকা ঘটনাগুলো থাকে। উদ্ধৃতি চিহ্নের ভেতরের বাক্যাংশ একসঙ্গে খোঁজা হয়। বড়/ছোট হাতের অক্ষর ও টুপি চিহ্নের পার্থক্য ধরা হয় না।", "f889bcce"],
