"Kısa bir turla ekrandaki her parçayı tanıtalım. İleri düğmesine dokunarak ilerleyin; istediğiniz an Geç diyebilirsiniz.":["একটি সংক্ষিপ্ত ভ্রমণে পর্দার প্রতিটি অংশের পরিচয় দিই। \"পরবর্তী\" বোতামে ট্যাপ করে এগিয়ে যান; যেকোনো মুহূর্তে \"এড়িয়ে যান\" বলতে পারেন।", "50479e1f"],
